#!/usr/bin/env node
// Embeds src/web/dist into the Worker bundle (src/generated/assets.ts, gitignored).
// Used by the preview deploy (wrangler.preview.toml, no [assets]): in this environment the
// HTTPS proxy overwrites the JWT that wrangler's /workers/assets/upload step needs → 401.
// `_headers` is parsed into a rules table and never embedded itself.
//
// Usage: node scripts/embed-assets.mjs              embed dist (fails if missing or > 5 MB)
//        node scripts/embed-assets.mjs --if-missing  only when the generated file is absent;
//                                                    writes an empty map (rules from
//                                                    web/public/_headers) if dist is absent too
//                                                    (keeps tests/typecheck working on a fresh checkout)
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, extname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const DIST = resolve(here, "../../web/dist");
const OUT = resolve(here, "../src/generated/assets.ts");
const MAX_BYTES = 5 * 1024 * 1024;
const SKIP = new Set(["/_headers", "/_redirects"]);

const TYPES = {
  ".html": ["text/html; charset=utf-8", true],
  ".js": ["text/javascript; charset=utf-8", true],
  ".mjs": ["text/javascript; charset=utf-8", true],
  ".css": ["text/css; charset=utf-8", true],
  ".json": ["application/json; charset=utf-8", true],
  ".webmanifest": ["application/manifest+json; charset=utf-8", true],
  ".map": ["application/json; charset=utf-8", true],
  ".svg": ["image/svg+xml; charset=utf-8", true],
  ".txt": ["text/plain; charset=utf-8", true],
  ".xml": ["application/xml; charset=utf-8", true],
  ".png": ["image/png", false],
  ".jpg": ["image/jpeg", false],
  ".jpeg": ["image/jpeg", false],
  ".webp": ["image/webp", false],
  ".avif": ["image/avif", false],
  ".gif": ["image/gif", false],
  ".ico": ["image/x-icon", false],
  ".woff": ["font/woff", false],
  ".woff2": ["font/woff2", false],
  ".wasm": ["application/wasm", false],
};

const write = (assets, rules) => {
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(
    OUT,
    `// GENERATED by scripts/embed-assets.mjs — do not edit, do not commit.\n` +
      `import type { EmbeddedAsset, HeaderRule } from "../static";\n\n` +
      `export const ASSET_MAP: Record<string, EmbeddedAsset> = ${JSON.stringify(assets, null, 1)};\n\n` +
      `export const HEADER_RULES: HeaderRule[] = ${JSON.stringify(rules, null, 1)};\n`,
  );
};

/** Cloudflare `_headers` format: unindented line = URL pattern, indented `Name: value` lines below it. */
export function parseHeaders(text) {
  const rules = [];
  let cur = null;
  for (const raw of text.split(/\r?\n/)) {
    if (!raw.trim() || raw.trim().startsWith("#")) continue;
    if (!/^\s/.test(raw)) {
      cur = { pattern: raw.trim(), headers: {} };
      rules.push(cur);
      continue;
    }
    if (!cur) throw new Error(`_headers: header line before any path: ${raw}`);
    const i = raw.indexOf(":");
    if (i < 0) throw new Error(`_headers: malformed line: ${raw}`);
    cur.headers[raw.slice(0, i).trim()] = raw.slice(i + 1).trim();
  }
  return rules;
}

const walk = (dir) =>
  readdirSync(dir).flatMap((n) => {
    const p = join(dir, n);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });

const ifMissing = process.argv.includes("--if-missing");
if (ifMissing && existsSync(OUT)) process.exit(0);
if (!existsSync(join(DIST, "index.html"))) {
  if (ifMissing) {
    const pub = resolve(here, "../../web/public/_headers");
    write({}, existsSync(pub) ? parseHeaders(readFileSync(pub, "utf8")) : []);
    console.log("embed-assets: no web build — wrote an empty asset map (+ public/_headers rules)");
    process.exit(0);
  }
  console.error(`embed-assets: ${DIST}/index.html not found — run \`npm run build:release\` first`);
  process.exit(1);
}

const assets = {};
let total = 0;
for (const file of walk(DIST).sort()) {
  const path = "/" + relative(DIST, file).split(sep).join("/");
  if (SKIP.has(path)) continue;
  const type = TYPES[extname(file).toLowerCase()];
  if (!type) {
    console.error(`embed-assets: unknown file type ${path}`);
    process.exit(1);
  }
  const buf = readFileSync(file);
  total += buf.length;
  const etag = `"${createHash("sha256").update(buf).digest("hex").slice(0, 32)}"`;
  assets[path] = type[1]
    ? { body: buf.toString("utf8"), base64: false, contentType: type[0], etag }
    : { body: buf.toString("base64"), base64: true, contentType: type[0], etag };
}
if (total > MAX_BYTES) {
  console.error(`embed-assets: ${(total / 1048576).toFixed(2)} MB exceeds the 5 MB limit — use [assets] instead`);
  process.exit(1);
}
const headersFile = join(DIST, "_headers");
const rules = existsSync(headersFile) ? parseHeaders(readFileSync(headersFile, "utf8")) : [];
write(assets, rules);
console.log(`embed-assets: ${Object.keys(assets).length} files, ${(total / 1024).toFixed(1)} KB, ${rules.length} header rules → src/generated/assets.ts`);
